package com.example

/**
 * 11 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 11 සිට 16 දක්වා (120 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 11 History Syllabus.
 */
object FlashcardBankHistoryGrade11SetsPart2 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> set11PostIndependenceDevelopment[(c - 1) % 20]
      12 -> set12ArchaeologicalSitesAndTriangle[(c - 1) % 20]
      13 -> set13Grade11MapMarkings[(c - 1) % 20]
      14 -> set14NationalHeroesAndServices[(c - 1) % 20]
      15 -> set15ExamQuestionsAndMastery[(c - 1) % 20]
      16 -> set16ColdWarAndNAM[(c - 1) % 20]
      else -> null
    }
  }

